using Microsoft.AspNetCore.DataProtection;

namespace FashionStore.Services.Implementations;

public static class StyleGame
{
    public static readonly string[] Products = ["Áo thun", "Quần jeans", "Giày sneaker"];
    public static readonly (string Name, string Hex)[] Colors =
    [
        ("Đen", "#181822"),
        ("Trắng", "#ffffff"),
        ("Xám", "#a5b2c3"),
        ("Kem", "#eddbb4"),
        ("Nâu", "#7b4327"),
        ("Xanh biển", "#2368d3"),
        ("Xanh đêm", "#18233b"),
        ("Ngọc lam", "#008670"),
        ("Xanh rêu", "#48691e"),
        ("Xanh chanh", "#8abf22"),
        ("Tím", "#7b43ce"),
        ("Đỏ", "#d62c36"),
        ("Đỏ rượu", "#86143b"),
        ("Cam", "#f47223"),
        ("Vàng", "#efaa22"),
        ("Hồng", "#de4574"),
        ("Đồng", "#ad6636")
    ];
    public static readonly string[] Stickers = ["★", "♥", "✿", "✦", "☀", "⚡"];

    // Alpha sampled at the center of each 40 × 40 scoring cell for the three studio photos.
    private static readonly string[] ProductMasks =
    [
        "",
        "",
        ""
    ];

    public static (int Score, int Coverage, int Palette, int Detail)? Evaluate(DesignSubmission design)
    {
        if (design.Product < 0 || design.Product >= Products.Length ||
            design.Marks == null || design.Marks.Count > 100)
            return null;

        const int gridSize = 40;
        var cells = new int[gridSize, gridSize];
        var points = 0;
        foreach (var mark in design.Marks)
        {
            if (mark == null || mark.Tool is not ("pen" or "eraser" or "sticker") ||
                mark.Size is < 4 or > 32 || mark.Color < 0 || mark.Color >= Colors.Length ||
                mark.Sticker < 0 || mark.Sticker >= Stickers.Length ||
                mark.Points == null || mark.Points.Count is < 1 or > 400 ||
                (mark.Tool == "sticker" && mark.Points.Count != 1))
                return null;
            points += mark.Points.Count;
            if (points > 5000) return null;

            DesignPoint? previous = null;
            foreach (var point in mark.Points)
            {
                if (point == null || !double.IsFinite(point.X) || !double.IsFinite(point.Y) ||
                    point.X is < 0 or > 1 || point.Y is < 0 or > 1)
                    return null;

                var start = previous ?? point;
                var steps = Math.Max(1, (int)Math.Ceiling(Math.Max(Math.Abs(point.X - start.X),
                    Math.Abs(point.Y - start.Y)) * gridSize));
                for (var step = 0; step <= steps; step++)
                {
                    var x = (int)((start.X + (point.X - start.X) * step / steps) * gridSize);
                    var y = (int)((start.Y + (point.Y - start.Y) * step / steps) * gridSize);
                    var radius = mark.Tool == "sticker" ? 1 : (int)Math.Round(mark.Size / 22d);
                    for (var dx = -radius; dx <= radius; dx++)
                    for (var dy = -radius; dy <= radius; dy++)
                    {
                        if (x + dx is >= 0 and < gridSize && y + dy is >= 0 and < gridSize &&
                            ProductMasks[design.Product][(y + dy) * gridSize + x + dx] == '1')
                            cells[x + dx, y + dy] = mark.Tool == "eraser" ? 0 :
                                mark.Tool == "sticker" ? Colors.Length + 1 : mark.Color + 1;
                    }
                }
                previous = point;
            }
        }

        var painted = cells.Cast<int>().Where(c => c > 0).ToList();
        var visibleColors = painted.Where(c => c <= Colors.Length).Distinct().Count();
        var coverage = Math.Min(45, painted.Count * 45 / 180);
        var palette = Math.Min(25, visibleColors * 8 + (visibleColors >= 3 ? 1 : 0));
        var detail = Math.Min(30, painted.Count * 20 / 90 + (painted.Contains(Colors.Length + 1) ? 10 : 0));
        return (coverage + palette + detail, coverage, palette, detail);
    }

    public static ITimeLimitedDataProtector RewardProtector(IDataProtectionProvider provider) =>
        provider.CreateProtector("FashionStore.DesignStudio.Reward.v1").ToTimeLimitedDataProtector();

    public static ITimeLimitedDataProtector RoundProtector(IDataProtectionProvider provider) =>
        provider.CreateProtector("FashionStore.DesignStudio.Round.v1").ToTimeLimitedDataProtector();
}

public record DesignSubmission(int Product, List<DesignMark> Marks);
public record DesignMark(string Tool, int Size, int Color, int Sticker, List<DesignPoint> Points);
public record DesignPoint(double X, double Y);
public record StyleReward(string UserId, string Code, int Score);
